"""Production writing admission markers with fake DB transport; no API or Android runtime."""
from pathlib import Path
import ast,os,subprocess,tempfile
S=Path(__file__).resolve().parents[1];B=S.parents[1]
jdk=Path(os.environ['JAVA_HOME']) if os.environ.get('JAVA_HOME') else next((B/'work/android-tools/jdk').iterdir())
android=Path(os.environ.get('ANDROID_HOME',str(B/'work/android-tools/sdk')))/'platforms/android-35/android.jar'
classes=B/'work/android-build-1.28.5/gradle/intermediates/javac/release/compileReleaseJavaWithJavac/classes'
cp=os.pathsep.join(map(str,[Path(os.environ.get('JSON_JAR',str(B/'work/android-test-tools/json.jar'))),classes,android]))
tree=ast.parse((S/'tests/test_event_context.py').read_text(encoding='utf-8-sig'))
original=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='sources' for t in n.targets))
sources={'android/util/Log.java':original['android/util/Log.java'],'android/content/ContentValues.java':original['android/content/ContentValues.java']}
sources.update({
'android/database/Cursor.java':r'''package android.database;public interface Cursor extends AutoCloseable{boolean moveToFirst();boolean moveToNext();String getString(int i);int getInt(int i);long getLong(int i);void close();}''',
'android/database/sqlite/SQLiteDatabase.java':r'''package android.database.sqlite;import android.database.*;import android.content.*;public class SQLiteDatabase{public static final int CONFLICT_REPLACE=5;public String letter,error="";public long revision;public int tries=1;final java.util.concurrent.locks.ReentrantLock lock=new java.util.concurrent.locks.ReentrantLock();public void beginTransaction(){lock.lock();}public void setTransactionSuccessful(){}public void endTransaction(){lock.unlock();}public int update(String table,ContentValues v,String where,String[] args){if(table.equals("letter_plans")){if(Long.parseLong(args[1])!=revision)return 0;letter=(String)v.get("body");revision=((Number)v.get("revision")).longValue();return 1;}if(v.containsKey("error"))error=(String)v.get("error");if(v.containsKey("tries"))tries=((Number)v.get("tries")).intValue();return 1;}public Cursor rawQuery(String q,String[] args){Object[] row=q.contains("character_life")?null:q.contains("count(*)")?new Object[]{0L}:q.contains("FROM writings")?null:q.contains("diary_attempts")?new Object[]{tries,0L,error}:new Object[]{letter};return new Cursor(){int index=-1;public boolean moveToFirst(){index=0;return row!=null;}public boolean moveToNext(){return ++index==0&&row!=null;}public String getString(int i){return row[i].toString();}public int getInt(int i){return ((Number)row[i]).intValue();}public long getLong(int i){return ((Number)row[i]).longValue();}public void close(){}};}}''',
'com/eidolon/sc/mobile/ChatStore.java':r'''package com.eidolon.sc.mobile;import org.json.*;import android.database.sqlite.*;public class ChatStore{final SQLiteDatabase db=new SQLiteDatabase();public SQLiteDatabase getWritableDatabase(){return db;}public SQLiteDatabase getReadableDatabase(){return db;}JSONObject personal()throws Exception{return new JSONObject().put("memoryEpoch",1);}}''',
'com/eidolon/sc/mobile/WritingAdmissionProbe.java':r'''package com.eidolon.sc.mobile;import org.json.*;import java.time.*;import java.util.*;public class WritingAdmissionProbe{
 static int n;static void check(boolean b,String s){if(!b)throw new AssertionError(s);n++;System.out.println("PASS "+s);}public static void main(String[] a)throws Exception{java.net.URL.setURLStreamHandlerFactory(p->{throw new AssertionError("No network permitted");});long now=Instant.parse("2026-11-08T08:00:00Z").toEpochMilli();ChatStore s=new ChatStore();JSONObject plan=new JSONObject().put("character","mano").put("date","2026-11-08").put("state","pending").put("revision",0).put("attempts",0).put("nextAttempt",now).put("deliverAt",now+3600000).put("text","").put("error","");s.db.letter=plan.toString();
 check(LetterPlanData.mayRequest(plan,now),"new due letter is eligible without extra model call");JSONObject legacy=new JSONObject(plan.toString()).put("attempts",1);check(!LetterPlanData.mayRequest(legacy,now),"legacy attempted request with unknown dispatch is not replayed");legacy.put("requestAttempted",false);check(LetterPlanData.mayRequest(legacy,now),"explicitly unsubmitted preparation retains original retry budget");
 long epoch=WritingStore.epoch.get();java.util.concurrent.atomic.AtomicInteger admitted=new java.util.concurrent.atomic.AtomicInteger();java.util.List<Throwable> errors=Collections.synchronizedList(new ArrayList<>());JSONObject c1=new JSONObject(plan.toString()),c2=new JSONObject(plan.toString());Thread t1=new Thread(()->{try{if(LetterPlanStore.markRequested(s,c1,epoch))admitted.incrementAndGet();}catch(Throwable e){errors.add(e);}}),t2=new Thread(()->{try{if(LetterPlanStore.markRequested(s,c2,epoch))admitted.incrementAndGet();}catch(Throwable e){errors.add(e);}});t1.start();t2.start();t1.join();t2.join();JSONObject persisted=new JSONObject(s.db.letter);check(errors.isEmpty()&&admitted.get()==1&&persisted.getBoolean("requestAttempted"),"production revision CAS persists one dispatch marker for concurrent workers");check(!LetterPlanData.mayRequest(persisted,now+1000)&&!LetterPlanStore.markRequested(s,persisted,epoch),"unknown reply is never automatically re-reserved");
 JSONObject frame=new JSONObject().put("enabled",true).put("baseMemoryEpoch",0);check(LetterPlanStore.ready(s,persisted,"旧理解写出的信",epoch,frame),"known stale writing result is finalized locally");JSONObject skipped=new JSONObject(s.db.letter);check(skipped.getString("state").equals("skipped")&&skipped.getString("text").isEmpty()&&!LetterPlanData.mayRequest(skipped,now),"changed understanding skips prepared letter instead of regenerating");
 WritingStore.epoch.incrementAndGet();check(!LetterPlanStore.markRequested(s,new JSONObject(plan.toString()),epoch),"restoration epoch rejects old preparation before dispatch");long live=WritingStore.epoch.get();
 check(DiaryStore.markRequested(s,"mano","2026-11-08",live),"production diary stores unknown-result marker before model attempt");JSONObject attempt=DiaryStore.attempt(s,"mano","2026-11-08");check(attempt.getInt("tries")==1&&attempt.getBoolean("requestUnknown"),"diary preserves actual attempt count instead of fabricating three attempts");check(!DiaryData.mayTry("2026-11-08",LocalDate.parse("2026-11-09"),now+86400000,attempt),"unknown diary request cannot become an automatic retry");DiaryStore.failed(s,"mano","2026-11-08","假服务断开",live);check(DiaryStore.attempt(s,"mano","2026-11-08").getBoolean("requestUnknown"),"failure preserves non-replay marker");
 DiaryStore.stopAutomatic(s,"mano","2026-11-08","依据已变化",live);check(s.db.tries==1&&DiaryStore.attempt(s,"mano","2026-11-08").getBoolean("requestUnknown"),"stale diary result consumes no invented extra calls");DiaryStore.resolved(s,"mano","2026-11-08",live);check(!DiaryStore.attempt(s,"mano","2026-11-08").getBoolean("requestUnknown"),"confirmed successful save resolves unknown marker");System.out.println("PASS "+n+" production writing no-replay admission cases; fake DB, zero network.");}
}'''
})
with tempfile.TemporaryDirectory(prefix='eidolon-writing-admission-') as tmp:
 root=Path(tmp);files=[]
 for name,text in sources.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8');files.append(str(p))
 subprocess.run([str(jdk/'bin/javac.exe'),'-encoding','UTF-8','-cp',cp,'-d',str(root),*files],check=True)
 subprocess.run([str(jdk/'bin/java.exe'),'-cp',str(root)+os.pathsep+cp,'com.eidolon.sc.mobile.WritingAdmissionProbe'],check=True)
